import java.awt.Color;

/**
 * Strategy interface for rendering simulation frames and formatting display text.
 */
public interface SimulationDisplayStrategy
{
    void setColor(Class<?> animalClass, Color color);

    String formatInfoText(SimulationDisplayContext context);

    String formatPopulationText(Field field);

    void render(SimulationDisplayContext context, GridCanvas canvas);

    boolean isViable(Field field);
}

import java.awt.Color;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Default rendering strategy for the simulator UI.
 */
public class DefaultSimulationDisplayStrategy implements SimulationDisplayStrategy
{
    private static final Color EMPTY_COLOR = Color.white;
    private static final Color UNKNOWN_COLOR = Color.gray;
    private static final Color INFECTED_COLOR = Color.green;
    private static final Color STORM_COLOR = Color.blue;

    private static final String DAYTIME_TEXT = "daytime";
    private static final String NIGHT_TEXT = "night";

    private final Map<Class<?>, Color> colors;
    private final FieldStats stats;

    public DefaultSimulationDisplayStrategy()
    {
        colors = new HashMap<>();
        stats = new FieldStats();
        registerDefaultColors();
    }

    @Override
    public void setColor(Class<?> animalClass, Color color)
    {
        colors.put(animalClass, color);
    }

    @Override
    public String formatInfoText(SimulationDisplayContext context)
    {
        return "It is: " + (context.isTimeOfDay() ? DAYTIME_TEXT : NIGHT_TEXT)
            + "        Oxygen Level: " + (int)(context.getOxygenLevel() * 100) + "%"
            + "        Storm: " + (context.getWeather().getStormStart() ? "exists" : "subsides");
    }

    @Override
    public String formatPopulationText(Field field)
    {
        return stats.getPopulationDetails(field);
    }

    @Override
    public void render(SimulationDisplayContext context, GridCanvas canvas)
    {
        Field field = context.getField();
        stats.reset();
        canvas.preparePaint();

        Set<Location> stormLocations = stormLocations(context);
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                Object creature = field.getObjectAt(row, col);
                Color color = EMPTY_COLOR;

                if(creature != null) {
                    stats.incrementCount(creature.getClass());
                    color = colorFor(creature);
                }

                if(stormLocations.contains(location)) {
                    color = STORM_COLOR;
                }

                canvas.drawMark(col, row, color);
            }
        }

        stats.countFinished();
        canvas.repaint();
    }

    @Override
    public boolean isViable(Field field)
    {
        return stats.isViable(field);
    }

    private void registerDefaultColors()
    {
        setColor(Cod.class, Color.ORANGE);
        setColor(Salmon.class, Color.YELLOW);
        setColor(Seaweed.class, Color.RED);
        setColor(Shark.class, Color.BLACK);
        setColor(Whale.class, Color.PINK);
        setColor(Weather.class, STORM_COLOR);
    }

    private Color colorFor(Object creature)
    {
        if(creature instanceof Animal) {
            Animal animal = (Animal)creature;
            if(animal.getIsInfected() && !animal.getIsImmuned()) {
                return INFECTED_COLOR;
            }
        }

        Color color = colors.get(creature.getClass());
        if(color == null) {
            return UNKNOWN_COLOR;
        }
        return color;
    }

    private Set<Location> stormLocations(SimulationDisplayContext context)
    {
        Set<Location> locations = new HashSet<>();
        Weather weather = context.getWeather();
        if(weather.getStormStart() && weather.getRandomLocation() != null) {
            locations.addAll(context.getField().adjacentLocationsIncludingSelf(weather.getRandomLocation(), weather.getStormScope()));
        }
        return locations;
    }
}

import java.awt.*;
import javax.swing.*;

/**
 * A graphical view of the simulation grid.
 *
 * @version 2022/03/02
 */
public class SimulatorView extends JFrame
{
    private static final String STEP_PREFIX = "Step: ";
    private static final String POPULATION_PREFIX = "Population: ";
    private static final String DAYOFTIME_PREFIX = "Time: It's ";
    private static final String POPULATION_DIE_OF_DISEASE_PREFIX = "Population died of disease: ";

    private JLabel stepLabel, population, infoLabel, diseaseLabel;
    private final FieldView fieldView;
    private final SimulationDisplayStrategy displayStrategy;

    /**
     * Create a view of the given width and height.
     * @param height The simulation's height.
     * @param width  The simulation's width.
     */
    public SimulatorView(int height, int width)
    {
        displayStrategy = new DefaultSimulationDisplayStrategy();

        setTitle("Underwater Environment Simulation");
        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
        infoLabel = new JLabel(DAYOFTIME_PREFIX + " ", JLabel.CENTER);
        diseaseLabel = new JLabel(POPULATION_DIE_OF_DISEASE_PREFIX, JLabel.CENTER);
        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);

        setLocation(100, 50);

        fieldView = new FieldView(height, width);

        Container contents = getContentPane();

        JPanel infoPane = new JPanel(new BorderLayout());
        infoPane.add(stepLabel, BorderLayout.WEST);
        infoPane.add(infoLabel, BorderLayout.CENTER);
        infoPane.add(diseaseLabel, BorderLayout.EAST);
        contents.add(infoPane, BorderLayout.NORTH);
        contents.add(fieldView, BorderLayout.CENTER);
        contents.add(population, BorderLayout.SOUTH);
        pack();
        setVisible(true);
    }

    /**
     * Define a color to be used for a given class of animal.
     * @param animalClass The animal's Class object.
     * @param color The color to be used for the given class.
     */
    public void setColor(Class<?> animalClass, Color color)
    {
        displayStrategy.setColor(animalClass, color);
    }

    /**
     * Display a short information label at the top of the window.
     */
    public void setInfoText(String text)
    {
        infoLabel.setText(text);
    }

    /**
     * Show the current status of the field.
     * @param step Which iteration step it is.
     * @param field The field whose status is to be displayed.
     * @param weather the object of weather class
     * @param oxygenLevel the oxygen level that is to be displayed in the current step.
     */
    public void showStatus(int step, Field field, boolean timeOfDay, Weather weather, double oxygenLevel)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        SimulationDisplayContext context = new SimulationDisplayContext(step, field, timeOfDay, weather, oxygenLevel);
        stepLabel.setText(STEP_PREFIX + step);
        infoLabel.setText(displayStrategy.formatInfoText(context));
        diseaseLabel.setText(POPULATION_DIE_OF_DISEASE_PREFIX + Animal.populationDieOfDisease);
        displayStrategy.render(context, fieldView);
        population.setText(POPULATION_PREFIX + displayStrategy.formatPopulationText(field));
    }

    /**
     * Determine whether the simulation should continue to run.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        return displayStrategy.isViable(field);
    }

    /**
     * Provide a graphical view of a rectangular field.
     */
    private class FieldView extends JPanel implements GridCanvas
    {
        private final int GRID_VIEW_SCALING_FACTOR = 6;

        private int gridWidth, gridHeight;
        private int xScale, yScale;
        private Dimension size;
        private Graphics g;
        private Image fieldImage;

        /**
         * Create a new FieldView component.
         */
        public FieldView(int height, int width)
        {
            gridHeight = height;
            gridWidth = width;
            size = new Dimension(0, 0);
        }

        /**
         * Tell the GUI manager how big we would like to be.
         */
        public Dimension getPreferredSize()
        {
            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
        }

        /**
         * Prepare for a new round of painting.
         */
        public void preparePaint()
        {
            if(!size.equals(getSize())) {
                size = getSize();
                fieldImage = fieldView.createImage(size.width, size.height);
                g = fieldImage.getGraphics();

                xScale = size.width / gridWidth;
                if(xScale < 1) {
                    xScale = GRID_VIEW_SCALING_FACTOR;
                }
                yScale = size.height / gridHeight;
                if(yScale < 1) {
                    yScale = GRID_VIEW_SCALING_FACTOR;
                }
            }
        }

        /**
         * Paint on grid location on this field in a given color.
         */
        public void drawMark(int x, int y, Color color)
        {
            g.setColor(color);
            g.fillRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
        }

        /**
         * The field view component needs to be redisplayed.
         */
        public void paintComponent(Graphics g)
        {
            super.paintComponent(g);
            if(fieldImage != null) {
                Dimension currentSize = getSize();
                if(size.equals(currentSize)) {
                    g.drawImage(fieldImage, 0, 0, null);
                }
                else {
                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
                }
            }
        }
    }
}

